package com.weaponsregistration.sales.service;
import com.weaponsregistration.sales.model.SaleReturnReasonType;import jakarta.persistence.EntityManager;import org.springframework.boot.*;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class SaleReturnReferenceData implements ApplicationRunner{private final EntityManager em;public SaleReturnReferenceData(EntityManager em){this.em=em;}@Override@Transactional public void run(ApplicationArguments a){seed("CUSTOMER_RETURN","Customer return",10);seed("ORDER_ERROR","Order error",20);seed("DEFECTIVE_ITEM","Defective item",30);}private void seed(String c,String n,int o){if(em.createQuery("select count(r) from SaleReturnReasonType r where r.code=:c",Long.class).setParameter("c",c).getSingleResult()==0){var r=new SaleReturnReasonType();r.code=c;r.name=n;r.displayOrder=o;r.systemProtected=true;em.persist(r);}}}
